def panel(prayers, rubrics):
    return {
        "credos": [
            {**prayers["signo"], "rubrica": rubrics["start"]},
            prayers["credo"],
        ],
        "padrenuestro": [{**prayers["padre"], "rubrica": rubrics["decade_start"]}],
        "tresavemarias": [
            {**prayers["aveFe"], "rubrica": rubrics["start_rosary"], "titulo": rubrics["three_hail_marys"]},
            {**prayers["aveEsperanza"], "rubrica": rubrics["hope"], "titulo": ""},
            {**prayers["aveCaridad"], "rubrica": rubrics["charity"], "titulo": ""},
        ],
        "avemaria": [{**prayers["ave"], "rubrica": rubrics["ten_times"]}],
        "gloriapatri": [{**prayers["gloria"], "rubrica": rubrics["decade_end"]}],
        "fatima": [{**prayers["fatima"], "rubrica": rubrics["fatima"]}],
        "salve": [{**prayers["salve"], "rubrica": rubrics["final"]}],
    }


def catalog(label, ui, tabs, weekdays, mysteries, prayers, rosary, rubrics):
    return {
        "meta": {"status": "available", "label": label, "review": "draft-human-review-needed"},
        "ui": ui,
        "prayerTabs": tabs,
        "weekdays": weekdays,
        "mysteries": mysteries,
        "prayers": prayers,
        "prayerPanels": panel(prayers, rubrics),
        "rosary": rosary,
    }


