def derived(code, label, words):
    en = BASE_TRANSLATIONS["en"]
    t = {**en, **words}
    prayers = {key: {"rubrica": r, "titulo": title, "texto": text} for key, (r, title, text) in t["prayers"].items()}
    rosary_tuple = t["rosary"]
    rubrics_tuple = t["rubrics"]
    return catalog(
        label,
        {
            "appTitle": t["title"], "rosaryPageTitle": t["rosaryPage"], "navMysteries": t["mysteries"], "navPrayers": t["prayersNav"],
            "navAbout": t["about"], "navStart": t["start"], "navHome": t["home"], "heroEyebrow": t["eyebrow"], "heroSubtitle": t["subtitle"],
            "dailyReading": t["daily"], "verseLoading": t["loading"], "verseError": t["error"], "heroGuide": t["guide"],
            "mysteriesEyebrow": t["four"], "mysteriesTitle": t["mystTitle"], "mysteriesToday": t["today"], "mysteriesIntro": t["intro"],
            "prayersEyebrow": t["full"], "prayersTitle": t["prayersTitle"], "aboutEyebrow": t["about"], "aboutTitle": t["aboutTitle"],
            "aboutText": t["aboutText"], "aboutLink": t["aboutLink"], "languageLabel": "Language", "languageSelectLabel": "Language",
            "rosaryOptionsLabel": t["options"], "rosaryImageLabel": t["image"], "nextPrayer": t["next"], "restart": t["restart"],
            "showPrayerGuide": t["showGuide"], "preparation": t["prep"], "closing": t["close"], "goTo": t["goTo"], "count": t["count"],
        },
        [{"id": k, "label": v} for k, v in zip(["o-credos", "o-padrenuestro", "o-tresavemarias", "o-avemaria", "o-gloriapatri", "o-fatima", "o-salve"], t["tabs"])],
        [{"nombre": name, "tipo": tipo} for name, tipo in zip(t["days"], ["gloriosos", "gozosos", "dolorosos", "gloriosos", "luminosos", "dolorosos", "gozosos"])],
        {k: {"panelId": f"m-{k}", "titulo": title, "dia": t["dayShort"][k], "nombres": names} for k, (title, names) in t["mnames"].items()},
        prayers,
        {"mysteryAnnouncement": rosary_tuple[0], "mysteryAnnouncementText": rosary_tuple[1], "faith": rosary_tuple[2], "hope": rosary_tuple[3], "charity": rosary_tuple[4], "ofTen": rosary_tuple[5]},
        {"start": rubrics_tuple[0], "decade_start": rubrics_tuple[1], "start_rosary": rubrics_tuple[2], "hope": rubrics_tuple[3], "charity": rubrics_tuple[4], "ten_times": rubrics_tuple[5], "decade_end": rubrics_tuple[6], "fatima": rubrics_tuple[7], "final": rubrics_tuple[8], "three_hail_marys": rubrics_tuple[9]},
    )


