DATA["it"]["prayers"] = {
    "signo": {"rubrica": "Apertura", "titulo": "Segno della Croce", "texto": "Per il segno della Santa Croce, liberaci, Signore Dio nostro, dai nostri nemici.\n\nNel nome del Padre, del Figlio e dello Spirito Santo. Amen."},
    "credo": {"rubrica": "Atto di fede", "titulo": "Credo Apostolico", "texto": "Io credo in Dio, Padre onnipotente, creatore del cielo e della terra. E in Gesù Cristo, suo unico Figlio, nostro Signore, il quale fu concepito di Spirito Santo, nacque da Maria Vergine, patì sotto Ponzio Pilato, fu crocifisso, morì e fu sepolto; discese agli inferi; il terzo giorno risuscitò da morte; salì al cielo, siede alla destra di Dio Padre onnipotente; di là verrà a giudicare i vivi e i morti. Credo nello Spirito Santo, la santa Chiesa cattolica, la comunione dei santi, la remissione dei peccati, la risurrezione della carne, la vita eterna. Amen."},
    "padre": {"rubrica": "Preghiera del Signore", "titulo": "Padre Nostro", "texto": "Padre nostro, che sei nei cieli, sia santificato il tuo nome; venga il tuo regno; sia fatta la tua volontà, come in cielo così in terra.\n\nDacci oggi il nostro pane quotidiano; rimetti a noi i nostri debiti, come anche noi li rimettiamo ai nostri debitori; e non abbandonarci alla tentazione, ma liberaci dal male. Amen."},
    "ave": {"rubrica": "Saluto angelico", "titulo": "Ave Maria", "texto": "Ave Maria, piena di grazia, il Signore è con te; tu sei benedetta fra le donne, e benedetto è il frutto del tuo seno, Gesù.\n\nSanta Maria, Madre di Dio, prega per noi peccatori, adesso e nell'ora della nostra morte. Amen."},
    "aveFe": {"rubrica": "Figlia di Dio Padre", "titulo": "Ave Maria", "texto": "Ave Maria Santissima, Figlia di Dio Padre, Vergine purissima prima del parto; nelle tue mani affidiamo la nostra fede, perché tu la illumini.\n\nPiena di grazia, il Signore è con te; tu sei benedetta fra le donne, e benedetto è il frutto del tuo seno, Gesù.\n\nSanta Maria, Madre di Dio, prega per noi peccatori, adesso e nell'ora della nostra morte. Amen."},
    "aveEsperanza": {"rubrica": "Madre di Dio Figlio", "titulo": "Ave Maria", "texto": "Ave Maria Santissima, Madre di Dio Figlio, Vergine purissima nel parto; nelle tue mani affidiamo la nostra speranza, perché tu la sostenga.\n\nPiena di grazia, il Signore è con te; tu sei benedetta fra le donne, e benedetto è il frutto del tuo seno, Gesù.\n\nSanta Maria, Madre di Dio, prega per noi peccatori, adesso e nell'ora della nostra morte. Amen."},
    "aveCaridad": {"rubrica": "Sposa di Dio Spirito Santo", "titulo": "Ave Maria", "texto": "Ave Maria Santissima, Sposa di Dio Spirito Santo, Vergine purissima dopo il parto; nelle tue mani affidiamo la nostra carità, perché tu la infiammi.\n\nPiena di grazia, il Signore è con te; tu sei benedetta fra le donne, e benedetto è il frutto del tuo seno, Gesù.\n\nSanta Maria, Madre di Dio, prega per noi peccatori, adesso e nell'ora della nostra morte. Amen."},
    "gloria": {"rubrica": "Dossologia", "titulo": "Gloria al Padre", "texto": "Gloria al Padre, al Figlio e allo Spirito Santo. Come era nel principio, ora e sempre, nei secoli dei secoli. Amen."},
    "fatima": {"rubrica": "Visione di Fatima · 1917", "titulo": "Preghiera di Fatima", "texto": "Gesù mio, perdona le nostre colpe, preservaci dal fuoco dell'inferno. Porta in cielo tutte le anime, specialmente le più bisognose della tua misericordia. Amen."},
    "salve": {"rubrica": "Preghiera finale", "titulo": "Salve Regina", "texto": "Salve, Regina, madre di misericordia, vita, dolcezza e speranza nostra, salve.\n\nA te ricorriamo, esuli figli di Eva; a te sospiriamo, gementi e piangenti in questa valle di lacrime. Orsù dunque, avvocata nostra, rivolgi a noi gli occhi tuoi misericordiosi; e mostraci, dopo questo esilio, Gesù, il frutto benedetto del tuo seno.\n\nO clemente, o pia, o dolce Vergine Maria. Amen."},
}
