DATA["fr"]["prayers"] = {
    "signo": {"rubrica": "Ouverture", "titulo": "Signe de la Croix", "texto": "Par le signe de la Sainte Croix, délivre-nous de nos ennemis, Seigneur notre Dieu.\n\nAu nom du Père, et du Fils, et du Saint-Esprit. Amen."},
    "credo": {"rubrica": "Acte de foi", "titulo": "Symbole des Apôtres", "texto": "Je crois en Dieu, le Père tout-puissant, créateur du ciel et de la terre. Et en Jésus-Christ, son Fils unique, notre Seigneur, qui a été conçu du Saint-Esprit, est né de la Vierge Marie, a souffert sous Ponce Pilate, a été crucifié, est mort et a été enseveli; est descendu aux enfers; le troisième jour est ressuscité des morts; est monté aux cieux, est assis à la droite de Dieu le Père tout-puissant, d'où il viendra juger les vivants et les morts. Je crois en l'Esprit Saint, à la sainte Église catholique, à la communion des saints, à la rémission des péchés, à la résurrection de la chair, à la vie éternelle. Amen."},
    "padre": {"rubrica": "Prière du Seigneur", "titulo": "Notre Père", "texto": "Notre Père, qui es aux cieux, que ton nom soit sanctifié; que ton règne vienne; que ta volonté soit faite sur la terre comme au ciel.\n\nDonne-nous aujourd'hui notre pain de ce jour; pardonne-nous nos offenses, comme nous pardonnons aussi à ceux qui nous ont offensés; et ne nous laisse pas entrer en tentation, mais délivre-nous du mal. Amen."},
    "ave": {"rubrica": "Salutation angélique", "titulo": "Je vous salue Marie", "texto": "Je vous salue Marie, pleine de grâce; le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni.\n\nSainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l'heure de notre mort. Amen."},
    "aveFe": {"rubrica": "Fille de Dieu le Père", "titulo": "Je vous salue Marie", "texto": "Je vous salue Marie très sainte, Fille de Dieu le Père, Vierge très pure avant l'enfantement; entre vos mains nous confions notre foi, afin que vous l'éclairiez.\n\nPleine de grâce, le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni.\n\nSainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l'heure de notre mort. Amen."},
    "aveEsperanza": {"rubrica": "Mère de Dieu le Fils", "titulo": "Je vous salue Marie", "texto": "Je vous salue Marie très sainte, Mère de Dieu le Fils, Vierge très pure dans l'enfantement; entre vos mains nous confions notre espérance, afin que vous la souteniez.\n\nPleine de grâce, le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni.\n\nSainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l'heure de notre mort. Amen."},
    "aveCaridad": {"rubrica": "Épouse de Dieu le Saint-Esprit", "titulo": "Je vous salue Marie", "texto": "Je vous salue Marie très sainte, Épouse de Dieu le Saint-Esprit, Vierge très pure après l'enfantement; entre vos mains nous confions notre charité, afin que vous l'enflammiez.\n\nPleine de grâce, le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni.\n\nSainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l'heure de notre mort. Amen."},
    "gloria": {"rubrica": "Doxologie", "titulo": "Gloire au Père", "texto": "Gloire au Père, au Fils et au Saint-Esprit. Comme il était au commencement, maintenant et toujours, pour les siècles des siècles. Amen."},
    "fatima": {"rubrica": "Vision de Fatima · 1917", "titulo": "Prière de Fatima", "texto": "Ô mon Jésus, pardonnez-nous nos péchés, préservez-nous du feu de l'enfer. Conduisez au ciel toutes les âmes, surtout celles qui ont le plus besoin de votre miséricorde. Amen."},
    "salve": {"rubrica": "Prière finale", "titulo": "Salut, ô Reine", "texto": "Salut, ô Reine, Mère de miséricorde, notre vie, notre douceur et notre espérance, salut.\n\nVers vous nous crions, pauvres enfants d'Ève exilés; vers vous nous soupirons, gémissant et pleurant dans cette vallée de larmes. Ô vous, notre avocate, tournez vers nous vos regards miséricordieux; et après cet exil, montrez-nous Jésus, le fruit béni de vos entrailles.\n\nÔ clémente, ô pieuse, ô douce Vierge Marie. Amen."},
}
