DATA["vi"]["prayers"] = {
    "signo": {"rubrica": "Mở đầu", "titulo": "Dấu Thánh Giá", "texto": "Nhờ dấu Thánh Giá, xin Chúa là Thiên Chúa chúng con cứu chúng con khỏi kẻ thù.\n\nNhân danh Cha, và Con, và Thánh Thần. Amen."},
    "credo": {"rubrica": "Tuyên xưng đức tin", "titulo": "Kinh Tin Kính các Tông Đồ", "texto": "Tôi tin kính Đức Chúa Trời là Cha phép tắc vô cùng dựng nên trời đất. Tôi tin kính Đức Chúa Giêsu Kitô là Con Một Đức Chúa Cha, cùng là Chúa chúng tôi; bởi phép Đức Chúa Thánh Thần mà Người xuống thai, sinh bởi Bà Maria đồng trinh; chịu nạn đời quan Phongxiô Philatô, chịu đóng đinh trên cây Thánh Giá, chết và táng xác; xuống ngục tổ tông; ngày thứ ba bởi trong kẻ chết mà sống lại; lên trời, ngự bên hữu Đức Chúa Cha phép tắc vô cùng; ngày sau bởi trời lại xuống phán xét kẻ sống và kẻ chết. Tôi tin kính Đức Chúa Thánh Thần, tôi tin có Hội Thánh hằng có ở khắp thế này, các thánh thông công, tôi tin phép tha tội, tôi tin xác loài người ngày sau sống lại, tôi tin hằng sống vậy. Amen."},
    "padre": {"rubrica": "Kinh của Chúa", "titulo": "Kinh Lạy Cha", "texto": "Lạy Cha chúng con ở trên trời, chúng con nguyện danh Cha cả sáng; nước Cha trị đến; ý Cha thể hiện dưới đất cũng như trên trời.\n\nXin Cha cho chúng con hôm nay lương thực hằng ngày; và tha nợ chúng con, như chúng con cũng tha kẻ có nợ chúng con; xin chớ để chúng con sa chước cám dỗ, nhưng cứu chúng con cho khỏi sự dữ. Amen."},
    "ave": {"rubrica": "Lời chào của thiên thần", "titulo": "Kinh Kính Mừng", "texto": "Kính mừng Maria đầy ơn phúc, Đức Chúa Trời ở cùng Bà; Bà có phúc lạ hơn mọi người nữ, và Giêsu con lòng Bà gồm phúc lạ.\n\nThánh Maria, Đức Mẹ Chúa Trời, cầu cho chúng con là kẻ có tội, khi nay và trong giờ lâm tử. Amen."},
    "aveFe": {"rubrica": "Con gái Thiên Chúa Cha", "titulo": "Kinh Kính Mừng", "texto": "Kính mừng Maria rất thánh, Con gái Thiên Chúa Cha, Trinh Nữ rất tinh tuyền trước khi sinh con; trong tay Mẹ chúng con phó thác đức tin của chúng con, xin Mẹ soi sáng.\n\nĐầy ơn phúc, Đức Chúa Trời ở cùng Bà; Bà có phúc lạ hơn mọi người nữ, và Giêsu con lòng Bà gồm phúc lạ.\n\nThánh Maria, Đức Mẹ Chúa Trời, cầu cho chúng con là kẻ có tội, khi nay và trong giờ lâm tử. Amen."},
    "aveEsperanza": {"rubrica": "Mẹ Thiên Chúa Con", "titulo": "Kinh Kính Mừng", "texto": "Kính mừng Maria rất thánh, Mẹ Thiên Chúa Con, Trinh Nữ rất tinh tuyền khi sinh con; trong tay Mẹ chúng con phó thác niềm hy vọng của chúng con, xin Mẹ nâng đỡ.\n\nĐầy ơn phúc, Đức Chúa Trời ở cùng Bà; Bà có phúc lạ hơn mọi người nữ, và Giêsu con lòng Bà gồm phúc lạ.\n\nThánh Maria, Đức Mẹ Chúa Trời, cầu cho chúng con là kẻ có tội, khi nay và trong giờ lâm tử. Amen."},
    "aveCaridad": {"rubrica": "Bạn trăm năm của Chúa Thánh Thần", "titulo": "Kinh Kính Mừng", "texto": "Kính mừng Maria rất thánh, Bạn trăm năm của Chúa Thánh Thần, Trinh Nữ rất tinh tuyền sau khi sinh con; trong tay Mẹ chúng con phó thác đức mến của chúng con, xin Mẹ làm bừng cháy.\n\nĐầy ơn phúc, Đức Chúa Trời ở cùng Bà; Bà có phúc lạ hơn mọi người nữ, và Giêsu con lòng Bà gồm phúc lạ.\n\nThánh Maria, Đức Mẹ Chúa Trời, cầu cho chúng con là kẻ có tội, khi nay và trong giờ lâm tử. Amen."},
    "gloria": {"rubrica": "Vinh tụng ca", "titulo": "Kinh Sáng Danh", "texto": "Sáng danh Đức Chúa Cha, và Đức Chúa Con, và Đức Chúa Thánh Thần. Như đã có trước vô cùng, và bây giờ, và hằng có, và đời đời chẳng cùng. Amen."},
    "fatima": {"rubrica": "Thị kiến Fatima · 1917", "titulo": "Kinh Fatima", "texto": "Lạy Chúa Giêsu, xin tha tội cho chúng con, xin cứu chúng con khỏi lửa hỏa ngục. Xin đưa các linh hồn lên thiên đàng, nhất là những linh hồn cần đến lòng thương xót Chúa hơn. Amen."},
    "salve": {"rubrica": "Kinh kết thúc", "titulo": "Kính chào Nữ Vương", "texto": "Kính chào Nữ Vương, Mẹ nhân lành, làm cho chúng con được sống, được vui, được cậy.\n\nThân lạy Mẹ, chúng con con cháu Evà ở chốn khách đày kêu đến cùng Bà; chúng con ở nơi khóc lóc than thở kêu khẩn Bà thương. Hỡi ôi, Bà là Chủ bầu chúng con, xin ghé mắt thương xem chúng con; đến sau khỏi đày, xin cho chúng con được thấy Đức Chúa Giêsu, con lòng Bà gồm phúc lạ.\n\nÔi khoan thay, nhân thay, dịu thay, Thánh Maria trọn đời đồng trinh. Amen."},
}
