for code, groups in MYSTERY_OVERRIDES.items():
    for key, (title, names) in groups.items():
        DATA[code]["mysteries"][key]["titulo"] = title
        DATA[code]["mysteries"][key]["nombres"] = names

for code, messages in DATA.items():
    if code not in AVAILABLE_LANGUAGES:
        messages["meta"]["status"] = "pending"


def write_js(code, data):
    content = (
        "window.SANTO_ROSARIO_I18N_MESSAGES = window.SANTO_ROSARIO_I18N_MESSAGES || {};\n\n"
        f"window.SANTO_ROSARIO_I18N_MESSAGES.{code} = "
        + json.dumps(data, ensure_ascii=False, indent=2)
        + ";\n"
    )
    (OUT / f"{code}.js").write_text(content, encoding="utf-8")


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    registry = "window.SANTO_ROSARIO_DEFAULT_LANGUAGE = 'es';\n\nwindow.SANTO_ROSARIO_LANGUAGES = "
    registry += json.dumps(
        [{"code": c, "name": n, "nativeName": nn, "status": "available" if c in AVAILABLE_LANGUAGES else "pending", "markets": m} for c, n, nn, m in LANGUAGES],
        ensure_ascii=False,
        indent=2,
    )
    registry += ";\n"
    (OUT / "languages.js").write_text(registry, encoding="utf-8")
    for code, *_ in LANGUAGES:
        write_js(code, DATA[code])


if __name__ == "__main__":
    main()
